package edu.hfut.appointment.service.impl;
import java.util.*;import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.Value;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.scheduling.annotation.*;import com.fasterxml.jackson.databind.ObjectMapper;import edu.hfut.appointment.dao.*;import edu.hfut.appointment.client.*;import edu.hfut.appointment.dto.*;import edu.hfut.appointment.entity.Appointment;import edu.hfut.appointment.exception.ApiException;import edu.hfut.appointment.security.RecoveryCipher;
@Service @EnableScheduling public class FinalApprovalService{
 public static final String UNKNOWN="签发结果尚未确认，请勿重复生成凭证，请联系管理员核实";
 private final AppointmentMapper appointments;private final IssuanceMapper operations;private final UserDirectory users;private final BlacklistClient blacklist;private final IssuanceClient access;private final RecoveryCipher cipher;private final ObjectMapper json;private final TransactionTemplate tx;
 @Value("${P3_INTERNAL_KEY}")String key;@Value("${p4.final.enabled:false}")boolean enabled;@Value("${p4.internal.enabled:false}")boolean internal;
 public FinalApprovalService(AppointmentMapper a,IssuanceMapper o,UserDirectory u,BlacklistClient b,IssuanceClient c,RecoveryCipher cipher,ObjectMapper j,PlatformTransactionManager manager){appointments=a;operations=o;users=u;blacklist=b;access=c;this.cipher=cipher;json=j;tx=new TransactionTemplate(manager);tx.setIsolationLevel(org.springframework.transaction.TransactionDefinition.ISOLATION_READ_COMMITTED);}
 private String text(Map<String,Object>m,String k){return m==null||m.get(k)==null?"":String.valueOf(m.get(k));}
 private Map<String,Object>map(Object...p){Map<String,Object>m=new LinkedHashMap<>();for(int i=0;i<p.length;i+=2)m.put(String.valueOf(p[i]),p[i+1]);return m;}
 private WriteContext identity(String token){WriteContext c=users.resolve(key,"Bearer "+token,Collections.singletonMap("action","review"));if(c==null||c.unavailable||c.actor==null)throw new ApiException(503,"身份验证服务不可用");return c;}
 public boolean routes(String token,Map<String,Object>b){return enabled&&"已通过".equals(b.get("status"))&&"admin".equals(identity(token).actor.role);}
 private void safety(Appointment a){BlacklistClient.Result r=blacklist.check(key,Collections.singletonMap("credential",a.idNumber==null?"":a.idNumber));if(r==null||!r.available||r.blocked==null)throw new ApiException(503,"黑名单服务不可用");if(r.blocked)throw new ApiException(403,"该访客身份证号已在黑名单中，禁止通过预约");}
 public Object approve(String token,String id,Map<String,Object>b){
  WriteContext actor=identity(token);if(!"admin".equals(actor.actor.role))throw new ApiException(403,"当前角色无权审核预约");
  tx.execute(s->{Appointment a=appointments.lock(id);if(a==null)throw new ApiException(404,"预约不存在");safety(a);Map<String,Object>existing=operations.one(id);if(existing!=null){if(!Objects.equals(existing.get("actor_id"),actor.actor.id))throw new ApiException(503,UNKNOWN);return null;}if(!"待保卫处审核".equals(a.status))throw new ApiException(400,"当前预约不在保卫处审核阶段");
   if(a.visitorId==null||a.visitorId.isEmpty())throw new ApiException(503,"预约未绑定人员，暂不能完成安全签发");
   String operation=UUID.randomUUID().toString();Map<String,Object>payload=map("operationId",operation,"appointmentId",a.id,"ownerId",a.visitorId,"ownerName",a.visitor,"validFrom",a.visitStart,"validTo",a.visitEnd==null||a.visitEnd.isEmpty()?a.visitStart:a.visitEnd,"comment",b.getOrDefault("comment",""),"reviewer",actor.actor.personName==null?actor.actor.username:actor.actor.personName);
   operations.insert(map("operationId",operation,"appointmentId",id,"actorId",actor.actor.id,"actorToken",cipher.encrypt(token),"payload",encode(payload),"version",a.version));return null;});
  drive(id);Map<String,Object>op=operations.one(id);if(op!=null&&"SUCCEEDED".equals(op.get("phase"))&&op.get("hold_reason")==null){Appointment a=appointments.one(id);safety(a);Map<String,Object>receipt;try{receipt=access.result(key,text(op,"operation_id"));}catch(Exception e){throw new ApiException(503,UNKNOWN);}Map<String,Object>q=(Map<String,Object>)receipt.get("qrCode");if(a!=null&&"已通过".equals(a.status)&&q!=null&&"有效".equals(q.get("status"))&&Objects.equals(q.get("appointmentId"),id))return map("appointment",a,"qrCode",q);throw new ApiException(409,"预约或通行凭证已失效，不能重放成功");}throw new ApiException(503,UNKNOWN);
 }
 private String encode(Object o){try{return json.writeValueAsString(o);}catch(Exception e){throw new IllegalStateException("Serialization failed");}}
 private Map<String,Object>payload(Map<String,Object>op){try{return json.readValue(text(op,"payload"),Map.class);}catch(Exception e){throw new IllegalStateException("Operation payload unavailable");}}
 private WriteContext authorize(Map<String,Object>op){WriteContext c=identity(cipher.decrypt(text(op,"actor_token")));if(!"admin".equals(c.actor.role)||!Objects.equals(c.actor.id,op.get("actor_id")))throw new ApiException(403,"原审批账号权限已变化");return c;}
 public Object decision(String operation){Map<String,Object>op=operations.operation(operation);if(op==null)return map("found",false);Appointment a=appointments.one(text(op,"appointment_id"));boolean valid=a!=null&&"已通过".equals(a.status)&&Arrays.asList("DECIDED","SUCCEEDED").contains(op.get("phase"))&&op.get("hold_reason")==null;
  if(valid&&!"SUCCEEDED".equals(op.get("phase")))try{authorize(op);safety(a);}catch(Exception e){valid=false;}
  boolean preparable=a!=null&&"待保卫处审核".equals(a.status)&&"PREPARE".equals(op.get("phase"))&&op.get("hold_reason")==null&&a.version.longValue()==((Number)op.get("expected_version")).longValue();if(preparable)try{authorize(op);safety(a);}catch(Exception e){preparable=false;}
  return map("found",true,"operationId",operation,"appointmentId",op.get("appointment_id"),"phase",op.get("phase"),"allowed",valid,"preparable",preparable,"payload",payload(op));
 }
 public Object status(String id){Map<String,Object>op=operations.one(id);return op==null?map("found",false):map("found",true,"operationId",op.get("operation_id"),"appointmentId",id,"phase",op.get("phase"),"holdReason",op.get("hold_reason"),"attempts",op.get("attempts"),"lastErrorCode",op.get("last_error_code"));}
 public void drive(String id){String owner=UUID.randomUUID().toString();if(operations.claim(id,owner)!=1)return;try{
  Map<String,Object>op=operations.one(id);if("SUCCEEDED".equals(op.get("phase"))||op.get("hold_reason")!=null)return;
  try{authorize(op);}catch(ApiException e){if(e.status==401||e.status==403){operations.hold(id,owner,"AUTHORIZATION_REVOKED");return;}throw e;}catch(com.netflix.hystrix.exception.HystrixBadRequestException e){operations.hold(id,owner,"AUTHORIZATION_REVOKED");return;}
  Appointment a=appointments.one(id);safety(a);String phase=text(op,"phase");Map<String,Object>command=payload(op);
  if("PREPARE".equals(phase)){
   if(a==null||!"待保卫处审核".equals(a.status)||a.version.longValue()!=((Number)op.get("expected_version")).longValue()){operations.hold(id,owner,"APPOINTMENT_CHANGED");return;}
   Map<String,Object>result=access.result(key,text(op,"operation_id"));if(!Boolean.TRUE.equals(result.get("found")))result=access.prepare(key,"Bearer "+cipher.decrypt(text(op,"actor_token")),command);if(!Boolean.TRUE.equals(result.get("found"))||!Objects.equals(result.get("operationId"),op.get("operation_id")))throw new IllegalStateException();
   authorize(op);final Map<String,Object>snapshot=op;tx.execute(s->{Appointment locked=appointments.lock(id);if(locked==null||!"待保卫处审核".equals(locked.status)||locked.version.longValue()!=((Number)snapshot.get("expected_version")).longValue())throw new ApiException(409,"预约状态已变化");locked.status="已通过";locked.reviewedAt=java.time.LocalDateTime.now(java.time.ZoneId.of("Asia/Shanghai")).format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"));locked.reviewer=text(command,"reviewer");locked.reviewComment=command.get("comment")==null?null:text(command,"comment");if(appointments.transition(locked,"待保卫处审核")!=1)throw new ApiException(409,"预约状态已变化");String event="P3-AUDIT-"+UUID.randomUUID();Map<String,Object>history=map("eventId",event,"appointmentId",id,"action","SECURITY_APPROVE","beforeStatus","待保卫处审核","afterStatus","已通过","version",locked.version+1,"actorId",snapshot.get("actor_id"),"actor",locked.reviewer,"role","admin","comment",locked.reviewComment,"occurredAt",locked.reviewedAt);appointments.insertHistory(history);appointments.insertOutbox(event,id,encode(history));if(operations.phase(id,owner,"DECIDED",null)!=1)throw new IllegalStateException("Operation lease changed");return null;});
  }
  op=operations.one(id);if("DECIDED".equals(op.get("phase"))){authorize(op);a=appointments.one(id);if(a==null||!"已通过".equals(a.status)){operations.hold(id,owner,"APPOINTMENT_CHANGED");return;}safety(a);Map<String,Object>receipt=access.result(key,text(op,"operation_id"));if(!"ACTIVE".equals(receipt.get("phase")))receipt=access.activate(key,command);Map<String,Object>q=(Map<String,Object>)receipt.get("qrCode");if(!"ACTIVE".equals(receipt.get("phase"))||q==null||!"有效".equals(q.get("status"))||!id.equals(q.get("appointmentId"))||!"visitor".equals(q.get("type"))||!Objects.equals(q.get("ownerId"),command.get("ownerId"))||!Objects.equals(q.get("validFrom"),command.get("validFrom"))||!Objects.equals(q.get("validTo"),command.get("validTo")))throw new IllegalStateException();authorize(op);operations.phase(id,owner,"SUCCEEDED",text(q,"id"));}
 }catch(com.netflix.hystrix.exception.HystrixBadRequestException e){operations.hold(id,owner,"SIGNING_REJECTED");}catch(Exception e){operations.unknown(id,owner);}finally{operations.release(id,owner);}}
 @Scheduled(fixedDelay=500)public void recover(){if(internal)for(String id:operations.due())drive(id);}
}
